/** Federal share of the combined rate, by country; everything else counts as regional. */
const FEDERAL_RATES: Record<string, number> = { CA: 0.05 };

/** Round away floating-point noise from subtracting rates. */
const clean = (n: number) => Math.round(n * 1e6) / 1e6;

/**
 * The federal and regional parts of `taxRateFor`, as fractions. They always
 * add up to the combined rate. Unknown regions are entirely regional.
 */
export function taxComponentsFor(
  address: Address,
  taxClass: TaxClass,
  fallback: number,
): { federal: number; regional: number } {
  const combined = taxRateFor(address, taxClass, fallback);
  const country = address.country.toUpperCase();
  const known = RATES[country]?.[address.region.toUpperCase()] !== undefined;
  const share = taxClass === 'reduced' ? REDUCED_SHARE : 1;
  const federal = known ? Math.min(FEDERAL_RATES[country] ?? 0, combined / share) * share : 0;
  return { federal: clean(federal), regional: clean(combined - federal) };
}
'''
